    const actionHub=roleActionHub({id:'family-next-action',kicker:'Your family at a glance',title:actionTitle,copy:actionCopy,actions:actionButtons,facts:[{icon:'heart',value:swimmers.swimmers.length,label:'active swimmers'},{icon:'calendar',value:confirmed.length,label:'confirmed lessons'},{icon:'bell',value:unread.length,label:'unread notices'},{icon:'thermometer',value:reading?.temperature!=null&&!wood?.reading_stale?`${Number(reading.temperature).toFixed(1)}°C`:'Check due',label:'Wood Street water'}]});
    content.innerHTML=shell(`Hello, ${session.user.first_name}.`,'Your lessons, progress and messages, all in one place.',`<div class="platform-grid">${actionHub}<nav class="family-quick-actions p-span-12" aria-label="Family shortcuts"><button data-route-jump="absences">${iconSvg('calendar')}<strong>Report an absence</strong><span>Tell us when you can’t attend</span></button><button data-route-jump="achievements">${iconSvg('heart')}<strong>Swimmer progress</strong><span>Skills and next steps</span></button><button data-route-jump="messages">${iconSvg('mail')}<strong>Message the team</strong><span>Ask a question privately</span></button><a href="programs.html#first-lesson">${iconSvg('check')}<strong>Get lesson-ready</strong><span>What to bring and expect</span></a></nav>${metric('Active swimmers',swimmers.swimmers.length,'Linked to your account','♡')}${metric('Confirmed lessons',confirmed.length,'Current recurring bookings','▦')}${metric('Wood Street water',reading?.temperature!=null&&!wood?.reading_stale?`${Number(reading.temperature).toFixed(1)}°C`:'Check due',reading?`Verified ${dt(reading.created_at)}`:'No staff reading','°C')}${metric('Bendigo weather',weather.current?.temperature_2m!=null?`${Math.round(weather.current.temperature_2m)}°C`:'—',weatherSummary(weather.current),'☀')}<section class="panel panel-pad p-span-7"><div class="panel-head"><h2>Your recurring lessons</h2><a class="btn btn-soft btn-small" href="enquire.html">Lesson enquiry</a></div><div class="api-list">${bookingRows||empty('No confirmed lessons yet.')}</div></section><section class="panel panel-pad p-span-5"><div class="panel-head"><h2>Latest notices</h2><button class="btn btn-soft btn-small" data-route-jump="notifications">View all</button></div><div class="api-list">${notes.notifications.slice(0,4).map(n=>`<div class="api-row"><div class="api-row-main"><strong>${esc(n.title)}</strong><span>${esc(n.message)}</span></div>${chip(n.read_at?'Read':'New',n.read_at?'demo':'changed')}</div>`).join('')||empty('No new notices.')}</div></section></div>`);
