  function swimmerSafetyMarkup(record) {
    const notes=[];
    if(record.allergies)notes.push(`<span class="safety-alert"><strong>Allergies</strong>${esc(record.allergies)}</span>`);
    if(record.medical_notes)notes.push(`<span><strong>Medical / safety</strong>${esc(record.medical_notes)}</span>`);
    if(record.medications)notes.push(`<span><strong>Medication</strong>${esc(record.medications)}</span>`);
    if(record.support_notes)notes.push(`<span><strong>Support</strong>${esc(record.support_notes)}</span>`);
    return notes.length?`<div class="register-safety-notes">${notes.join('')}</div>`:'<p>No allergy, medical or support details recorded.</p>';
  }

