    const termRows=terms.map(item=>`<tr><td><strong>${esc(item.name)}</strong><br><span class="micro">${item.source==='preview'?'Local preview only':`Created by ${esc(item.created_by_name||'management')}`}</span></td><td>${esc(dOnly(item.start_date))}–${esc(dOnly(item.end_date))}</td><td>${Number(item.absence_credit_limit)}</td><td>${Number(item.credits_recorded)}/${Number(item.absence_reports)} credited</td><td><div class="api-row-actions">${chip(item.status,item.status==='active'?'open':item.status==='draft'?'changed':'demo')}${item.status==='draft'?`<button class="btn btn-soft btn-small" type="button" data-action="activate-term" data-term-id="${Number(item.id)}" data-term-name="${esc(item.name)}">Activate</button>`:''}</div></td></tr>`).join('');
    const absenceRows=absences.map(item=>`<tr><td>${esc(dOnly(item.occurrence_date))}</td><td><strong>${esc(item.swimmer_first)} ${esc(item.swimmer_last)}</strong><br><span class="micro">Family: ${esc(item.customer_first)} ${esc(item.customer_last)}</span></td><td>${esc(item.code)} · ${esc(item.title)}<br><span class="micro">${esc(clockTime(item.start_time))} · ${esc(item.location_name)}</span></td><td>${esc(item.reason_category)}</td><td>${chip(item.credit_status==='credited'?'Credit recorded':'No credit remaining',item.credit_status==='credited'?'open':'changed')}</td></tr>`).join('');
    content.innerHTML=shell('Term operations','Publish the dates that drive lesson schedules, family absence credits and staff registers.',`<div class="platform-grid"><section class="term-status-banner p-span-12 ${active.in_session?'is-active':'is-blocked'}"><div><span class="role-action-kicker">Current calendar</span><h2>${active.configured?esc(active.name):'No active term is published'}</h2><p>${active.configured?`${esc(dOnly(active.start_date))}–${esc(dOnly(active.end_date))} · ${Number(active.absence_credit_limit)} absence credits per swimmer`:'Create and activate a term before family absence reporting and today’s lesson registers can operate.'}</p></div>${chip(active.is_preview?'Preview only':active.in_session?'In session':'Needs review',active.in_session?'open':'changed')}</section><section class="panel panel-pad p-span-5"><div class="panel-head"><div><h2>Create school term</h2><p>Activating closes the current active term.</p></div>${chip('Management only','changed')}</div><form class="platform-form" id="term-form"><div class="field full"><label for="term-name">Term name</label><input class="input" id="term-name" name="name" maxlength="100" placeholder="e.g. Term 1 2027" required></div><div class="field"><label for="term-start">Start date</label><input class="input" id="term-start" name="start_date" type="date" required></div><div class="field"><label for="term-end">End date</label><input class="input" id="term-end" name="end_date" type="date" required></div><div class="field full"><label for="term-credit-limit">Absence credits per swimmer</label><input class="input" id="term-credit-limit" name="absence_credit_limit" type="number" min="0" max="10" value="2" required></div><div class="field full"><label class="choice"><input type="checkbox" name="activate"> Publish this as the active operating term now</label></div><div class="field full"><button class="btn btn-blue" type="submit">Save term calendar</button></div></form><div class="data-boundary"><strong>Date safeguard:</strong> Use approved business dates. Preview dates are never treated as production truth.</div></section><section class="panel panel-pad p-span-7"><div class="panel-head"><div><h2>Term history</h2><p>Credit allowance and operational status</p></div>${chip(`${terms.length} terms`,'demo')}</div><div class="table-scroll-note" id="term-history-note">On a small screen, swipe sideways to review every term field.</div><div class="table-wrap" tabindex="0" role="region" aria-label="School term history" aria-describedby="term-history-note"><table class="data-table"><caption class="sr-only">Configured school terms and absence-credit usage</caption><thead><tr><th scope="col">Term</th><th scope="col">Dates</th><th scope="col">Credit limit</th><th scope="col">Absence records</th><th scope="col">Status</th></tr></thead><tbody>${termRows||'<tr><td colspan="5">No terms configured.</td></tr>'}</tbody></table></div></section><section class="panel panel-pad p-span-12"><div class="panel-head"><div><h2>Absence & credit ledger</h2><p>Family reports across configured terms</p></div>${chip(`${absences.length} reports`,absences.length?'changed':'demo')}</div><div class="table-scroll-note" id="absence-ledger-note">On a small screen, swipe sideways to review all operational fields.</div><div class="table-wrap" tabindex="0" role="region" aria-label="Absence and term-credit ledger" aria-describedby="absence-ledger-note"><table class="data-table"><caption class="sr-only">Reported lesson absences and recorded term-credit eligibility</caption><thead><tr><th scope="col">Date</th><th scope="col">Swimmer</th><th scope="col">Lesson</th><th scope="col">Reason</th><th scope="col">Credit</th></tr></thead><tbody>${absenceRows||'<tr><td colspan="5">No absences have been reported.</td></tr>'}</tbody></table></div><div class="data-boundary"><strong>Payment route:</strong> lesson/term charges and any approved financial credit belong in the authorised Xero invoicing workflow. This ledger does not create invoices, refunds or credit notes automatically.</div></section></div>`);
