  async function qualificationsViewV2(content) {
    const [data,staffData]=await Promise.all([load('/api/staff/qualifications'),session.user.role==='admin'?load('/api/admin/staff'):Promise.resolve({staff:[session.user]})]);
    const staffOptions=(staffData.staff||[]).filter(person=>person.active).map(person=>`<option value="${person.id}">${esc(person.first_name)} ${esc(person.last_name)}</option>`).join('');
    const cards=data.qualifications.map(item=>{const expiryLabel=item.days_remaining<0?`Expired ${Math.abs(item.days_remaining)} days ago`:item.days_remaining===0?'Expires today':`${item.days_remaining} days remaining`;return `<article class="qualification-document-card ${item.status}"><div class="qualification-document-icon" aria-hidden="true">${item.document_media_type==='application/pdf'?'PDF':'IMG'}</div><div class="qualification-document-copy"><span>${session.user.role==='admin'?esc(`${item.first_name} ${item.last_name}`):'My certificate'}</span><h3>${esc(item.qualification_type)}</h3><strong>Expires ${esc(dOnly(item.expiry_date))}</strong><small>${esc(expiryLabel)}</small></div><div class="qualification-document-actions">${chip(item.status,statusKind(item.status))}${item.document_url?`<a class="btn btn-soft btn-small" href="${esc(item.document_url)}" target="_blank" rel="noopener">View ${item.document_media_type==='application/pdf'?'PDF':'image'}</a>`:`<span class="status changed">Document required</span>`}</div></article>`}).join('');
    content.innerHTML=shell(session.user.role==='admin'?'Staff certificates & licences':'My certificates & licences','Store the actual certificate photo or PDF, show its expiry and remind the worker before renewal is due.',`<div class="platform-grid"><section class="panel panel-pad p-span-5"><div class="panel-head"><div><h2>Upload document</h2><p>PDF, PNG, JPG or WebP · maximum 5 MB.</p></div>${chip('Private staff record','open')}</div><form class="platform-form" id="qualification-document-form">${session.user.role==='admin'?`<div class="field full"><label for="qualification-staff">Worker</label><select id="qualification-staff" name="staff_id" required>${staffOptions}</select></div>`:''}<div class="field full"><label for="qualification-type">Certificate or licence</label><input class="input" id="qualification-type" name="qualification_type" list="qualification-types" maxlength="100" placeholder="e.g. CPR, WWCC, AUSTSWIM" required><datalist id="qualification-types"><option value="Working With Children Check"><option value="CPR"><option value="First Aid"><option value="AUSTSWIM Teacher of Swimming and Water Safety"><option value="Swim Australia Teacher"><option value="Autism Swim Approved Provider"></datalist></div><div class="field"><label for="qualification-expiry">Expiry date</label><input class="input" id="qualification-expiry" name="expiry_date" type="date" required></div><div class="field"><label for="qualification-reminder">Renewal reminder</label><select id="qualification-reminder" name="reminder_days"><option value="30">30 days before</option><option value="60" selected>60 days before</option><option value="90">90 days before</option><option value="120">120 days before</option></select></div><div class="field full"><label for="qualification-document">Certificate photo or PDF</label><input class="input file-input" id="qualification-document" name="document" type="file" accept="application/pdf,image/png,image/jpeg,image/webp,.pdf,.png,.jpg,.jpeg,.webp" required></div><div class="field full"><button class="btn btn-blue" type="submit">Upload certificate securely</button></div></form></section><section class="panel panel-pad p-span-7"><div class="panel-head"><div><h2>Certificate register</h2><p>The document and expiry date are the source record.</p></div>${chip(`${data.qualifications.length} records`,'open')}</div><div class="qualification-document-list">${cards||empty('No certificate documents have been uploaded yet.')}</div><div class="data-boundary"><strong>Renewal reminders:</strong> staff and management receive an in-portal reminder when a record reaches its selected renewal window. Email and SMS remain setup-required and are not simulated.</div></section></div>`);
  }

  const incidentTypeLabel=value=>({injury:'Injury',illness:'Illness',behaviour:'Behaviour / distress',near_miss:'Near miss',safeguarding:'Safeguarding concern',other:'Other incident'})[value]||String(value||'Incident');
  const incidentCards=(reports,{management=false,family=false}={})=>(reports||[]).map(report=>`<article class="incident-report-card"><div class="incident-report-head"><div><span>${esc(report.reference)} · ${esc(incidentTypeLabel(report.incident_type))}</span><h3>${esc(report.swimmer_first)} ${esc(report.swimmer_last)}</h3><p>${esc(report.swimmer_number)} · family ${esc(report.customer_number)} · ${esc(report.location_name)} · ${esc(dt(report.incident_at))}</p></div><div>${chip(report.status,statusKind(report.status))}<span class="incident-severity" data-severity="${esc(report.severity||'unassessed')}">${esc(({minor:'GREEN · Minor',moderate:'YELLOW · Moderate',serious:'ORANGE · Serious',critical:'RED · Critical'})[report.severity]||'Severity not assessed')}</span></div></div><dl class="incident-detail-grid"><div><dt>What happened</dt><dd>${esc(report.what_happened)}</dd></div><div><dt>Injury / symptoms observed</dt><dd>${esc(report.injury_observed||'None recorded')}</dd></div><div><dt>First aid applied</dt><dd>${esc(report.first_aid_applied||'None recorded')}</dd></div><div><dt>First aider</dt><dd>${esc(report.first_aider||'Not recorded')}</dd></div><div><dt>Emergency services</dt><dd>${report.emergency_services?'Contacted':'Not marked as contacted'}</dd></div><div><dt>Further action</dt><dd>${esc(report.further_action||'None recorded')}</dd></div><div><dt>Witnesses</dt><dd>${esc(report.witnesses||'None recorded')}</dd></div><div><dt>Parent notified</dt><dd>${report.parent_notified?'Yes':'Not marked as notified'}</dd></div></dl>${!family&&report.supporting_notes?`<div class="data-boundary"><strong>Staff-only supporting notes</strong><p>${esc(report.supporting_notes)}</p></div>`:''}${!family&&report.manager_review?`<div class="data-boundary"><strong>Management review · ${esc(dt(report.reviewed_at))}</strong><p>${esc(report.manager_review)}</p></div>`:''}<div class="incident-report-foot"><span>Reported by ${esc(report.reporter_first)} ${esc(report.reporter_last)} · ${esc(report.staff_number||'worker number pending')}</span>${management?`<form class="incident-status-form" data-incident-id="${Number(report.id)}"><label><span class="sr-only">Status for ${esc(report.reference)}</span><select name="status"><option value="open" ${report.status==='open'?'selected':''}>Open</option><option value="follow_up" ${report.status==='follow_up'?'selected':''}>Follow-up</option><option value="closed" ${report.status==='closed'?'selected':''}>Closed</option></select></label><label><span class="sr-only">Management review for ${esc(report.reference)}</span><textarea name="manager_review" maxlength="2000" rows="2" placeholder="Review and follow-up (staff only)"></textarea></label><button class="btn btn-soft btn-small" type="submit">Save review &amp; status</button></form>`:family?'<span>Contact HV Swim if any detail needs clarification.</span>':''}</div></article>`).join('');

  async function staffIncidents(content) {
    const data=await load('/api/staff/incidents');
    const management=session.user.role==='admin';
    const swimmers=data.swimmers.map(swimmer=>`<option value="${Number(swimmer.id)}">${esc(swimmer.first_name)} ${esc(swimmer.last_name)} · ${esc(swimmer.swimmer_number)} · family ${esc(swimmer.customer_number)}</option>`).join('');
    const locations=data.locations.map(location=>`<option value="${esc(location.slug)}">${esc(location.name)}</option>`).join('');
    const localNow=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);
    content.innerHTML=shell(management?'Incident & injury register':'Incident & injury reports',management?'Review reports, confirm follow-up and preserve the full accountable record.':'Record what happened, first aid, follow-up and parent notification against the correct child and family.',`<div class="platform-grid"><section class="panel panel-pad p-span-5"><div class="panel-head"><div><h2>New incident report</h2><p>Reporter ${esc(session.user.staff_number||'worker number pending')} is recorded automatically.</p></div>${chip('Private record','open')}</div><form class="platform-form" id="incident-report-form"><div class="field full"><label for="incident-swimmer">Child / family recipient</label><select id="incident-swimmer" name="swimmer_id" required><option value="">Choose the child by student and family number</option>${swimmers}</select></div><div class="field"><label for="incident-location">Location</label><select id="incident-location" name="location_slug" required>${locations}</select></div><div class="field"><label for="incident-at">Date and time</label><input class="input" id="incident-at" name="incident_at" type="datetime-local" value="${localNow}" required></div><div class="field full"><label for="incident-type">Report type</label><select id="incident-type" name="incident_type"><option value="injury">Injury</option><option value="illness">Illness</option><option value="behaviour">Behaviour / distress</option><option value="near_miss">Near miss</option><option value="safeguarding">Safeguarding concern</option><option value="other">Other incident</option></select></div><div class="field full"><label for="incident-severity">Severity</label><select id="incident-severity" name="severity" required><option value="">Choose a severity</option><option value="minor">GREEN — Minor</option><option value="moderate">YELLOW — Moderate</option><option value="serious">ORANGE — Serious</option><option value="critical">RED — Critical</option></select></div><div class="field full"><label for="incident-happened">What happened</label><textarea id="incident-happened" name="what_happened" rows="5" minlength="10" maxlength="3000" required placeholder="Record objective facts, the sequence of events and where the child was"></textarea></div><div class="field full"><label for="incident-injury">Injury or symptoms observed</label><textarea id="incident-injury" name="injury_observed" rows="3" maxlength="2000" placeholder="Describe visible injury or symptoms; do not diagnose"></textarea></div><div class="field full"><label for="incident-first-aid">First aid applied</label><textarea id="incident-first-aid" name="first_aid_applied" rows="3" maxlength="2000" placeholder="Who provided first aid, what was applied and when"></textarea></div><div class="field full"><label for="incident-action">Further action / handover</label><textarea id="incident-action" name="further_action" rows="3" maxlength="2000" placeholder="Parent handover, ambulance, medical advice, monitoring or follow-up required"></textarea></div><div class="field full"><label for="incident-witnesses">Witnesses</label><input class="input" id="incident-witnesses" name="witnesses" maxlength="500" placeholder="Names and roles only"></div><div class="field full"><label for="incident-first-aider">First aider name / worker number</label><input class="input" id="incident-first-aider" name="first_aider" maxlength="200"></div><div class="field full"><label for="incident-notes">Supporting notes (staff only)</label><textarea id="incident-notes" name="supporting_notes" maxlength="2000" rows="3"></textarea></div><label class="choice full"><input type="checkbox" name="emergency_services"> Emergency services contacted</label><label class="choice full"><input type="checkbox" name="parent_notified"> Parent or guardian has been notified</label><div class="field full"><button class="btn btn-primary" type="submit">Create private incident report</button></div></form><div class="data-boundary"><strong>Record carefully:</strong> write objective facts only. This form is not a substitute for emergency care, mandatory reporting, WorkSafe processes or management escalation.</div></section><section class="panel panel-pad p-span-7"><div class="panel-head"><div><h2>${management?'All incident reports':'Reports I created'}</h2><p>Sensitive details are visible only to authorised staff, management and the involved family.</p></div>${chip(`${data.reports.length} reports`,data.reports.some(item=>item.status!=='closed')?'changed':'open')}</div><div class="field"><label for="incident-filter">Filter reports</label><select id="incident-filter"><option value="">All reports</option><option value="open">Open / follow-up</option><option value="serious">Serious / critical</option><option value="closed">Closed</option></select></div><div class="incident-report-list" id="incident-results">${incidentCards(data.reports,{management})||empty('No incident reports are recorded in this view.')}</div></section></div>`);
    content.querySelector('#incident-filter').addEventListener('change',event=>{
      const value=event.target.value;
      const reports=data.reports.filter(report=>!value||(value==='open'?report.status!=='closed':value==='serious'?['serious','critical'].includes(report.severity):report.status==='closed'));
      content.querySelector('#incident-results').innerHTML=incidentCards(reports,{management})||empty('No reports match this filter.');
    });
  }

