    const invoiceCards=(data.invoices||[]).map(invoice=>{const canSync=invoice.status==='approved';const canRefresh=Boolean(invoice.xero_invoice_id);const timeline=(invoice.events||[]).slice(-5).reverse().map(event=>`<li><span></span><div><strong>${esc(invoiceEventLabel(event.event_type))}</strong><small>${esc(dt(event.created_at))}${event.actor_first?` · ${esc(event.actor_first)} ${esc(event.actor_last||'')}`:''}</small></div></li>`).join('');return `<article class="invoice-card admin-invoice-card"><div class="invoice-head"><div><span>${esc(invoice.invoice_number)} · ${esc(invoice.customer_number)}</span><h2>${esc(invoice.customer_first)} ${esc(invoice.customer_last)}</h2><p>${esc(invoice.term_name||'Lesson fees')} · issued ${esc(dOnly(invoice.issue_date))} · due ${esc(dOnly(invoice.due_date))}</p></div>${chip(invoiceStatusLabel(invoice.status),statusKind(invoice.status))}</div>${invoiceLinesMarkup(invoice.lines)}<div class="invoice-summary"><div><span>Total</span><strong>${money(invoice.total_cents)}</strong></div><div><span>Paid</span><strong>${money(invoice.amount_paid_cents)}</strong></div><div><span>Due</span><strong>${money(invoice.amount_due_cents)}</strong></div></div>${invoice.last_sync_error?`<div class="billing-sync-warning"><strong>Manual review required</strong><span>${esc(invoice.last_sync_error)}</span><small>Check the Xero organisation before taking any further action. The platform will not retry automatically.</small></div>`:''}<div class="invoice-workflow"><ol class="invoice-timeline">${timeline}</ol><div class="billing-action-row">${invoice.status==='draft'?`<button class="btn btn-blue btn-small" type="button" data-action="approve-invoice" data-invoice-id="${Number(invoice.id)}" data-invoice-number="${esc(invoice.invoice_number)}">Review &amp; approve</button>`:''}${canSync?`<button class="btn btn-primary btn-small" type="button" data-action="sync-xero-invoice" data-invoice-id="${Number(invoice.id)}" data-invoice-number="${esc(invoice.invoice_number)}" ${(data.xero.connection_status==='connected'&&data.xero.invoice_configuration_ready&&data.xero.outbound_enabled)?'':'disabled'}>Create Xero draft</button>`:''}${canRefresh?`<button class="btn btn-soft btn-small" type="button" data-action="refresh-xero-invoice" data-invoice-id="${Number(invoice.id)}">Refresh from Xero</button>`:''}</div></div><div class="invoice-foot"><span>${invoice.xero_invoice_id?`Xero ID ${esc(invoice.xero_invoice_id)} · ${esc(invoice.xero_status||'status pending')}`:'No Xero invoice created'}</span>${invoice.online_invoice_url?`<a href="${esc(invoice.online_invoice_url)}" target="_blank" rel="noopener">Open Xero invoice ↗</a>`:''}</div></article>`}).join('');
    const xeroReady=data.xero.oauth_configured&&data.xero.connection_status==='connected'&&data.xero.invoice_configuration_ready&&data.xero.outbound_enabled;
    content.innerHTML=shell('Billing & invoices','Create, approve and reconcile lesson invoices with a deliberate Xero draft workflow. Merchandise stays in Shopify.',`<div class="platform-grid">${metric('Unbilled lessons',money(data.summary.unbilled_cents),`${data.unbilled_charges.length} charge records ready for review`,'document')}${metric('Local drafts',data.summary.draft_count,'Not visible to families or Xero','status')}${metric('Approved',data.summary.approval_count,'Ready for an authorised Xero draft','check')}${metric('Outstanding',money(data.summary.outstanding_cents),'Approved or Xero-confirmed invoices','dollar')}<section class="billing-readiness p-span-12"><div><span class="role-action-kicker">Lesson payment control</span><h2>${xeroReady?'Xero draft transmission is ready':'Xero setup is deliberately gated'}</h2><p>Management reviews the family, student, term, lines and amount locally before any DRAFT invoice can be created in Xero.</p></div><div class="billing-readiness-checks">${chip(data.xero.connection_status==='connected'?'Xero connected':'Xero not connected',data.xero.connection_status==='connected'?'open':'changed')}${chip(data.xero.invoice_configuration_ready?'Invoice codes ready':'Account / tax setup needed',data.xero.invoice_configuration_ready?'open':'changed')}${chip(data.xero.outbound_enabled?'Outbound enabled':'Outbound locked',data.xero.outbound_enabled?'open':'demo')}</div></section><section class="panel panel-pad p-span-12"><div class="panel-head"><div><h2>Unbilled lesson charges</h2><p>Charges are separated by family and school term. Creating a local draft does not contact Xero.</p></div>${chip(`${grouped.length} family-term groups`,grouped.length?'changed':'open')}</div><div class="billing-family-groups">${draftGroups||empty('All current lesson charges have been assigned to an invoice.')}</div></section><section class="panel panel-pad p-span-12"><div class="panel-head"><div><h2>Invoice ledger</h2><p>Local review, Xero confirmation and payment status in one accountable history.</p></div>${chip(`${data.invoices.length} invoices`,'open')}</div><div class="invoice-ledger-list">${invoiceCards||empty('No invoice drafts have been created yet.')}</div></section><section class="panel panel-pad p-span-12 shopify-billing-boundary"><div><span>Merchandise payment route</span><h2>Shopify owns product checkout and orders</h2><p>The HV invoice ledger never turns merchandise into a Xero lesson invoice. Approved products continue through Shopify checkout; order reconciliation needs authorised Shopify customer/order access or the business’s accounting connector.</p></div><button class="btn btn-soft" data-route-jump="merch">Open merchandise operations</button></section><section class="panel panel-pad p-span-12"><div class="data-boundary" style="margin-top:0"><strong>Accounting boundary:</strong> Xero remains the accounting source of truth. A local “approved” status is not proof that Xero has created or sent an invoice. Only a confirmed Xero invoice ID changes the record to Xero draft. No credit note, refund, tax decision or blind retry is automated.</div></section></div>`);
