      if(action==='activate-term'){await api(`/api/admin/terms/${Number(target.dataset.termId)}/activate`,{method:'POST'});toast('School term activated. Calendar-based workflows now use these dates.');await renderRoute({preserveScroll:true});}
      if(action==='read-notification'){await api(`/api/notifications/${target.dataset.notificationId}/read`,{method:'POST'});await refreshNotificationCount();await renderRoute({preserveScroll:true});}
      if(action==='staff-clock'){const clockAction=target.dataset.clockAction;const locationSlug=document.getElementById('clock-location')?.value||'wood-street';const result=await api('/api/staff/clock',{method:'POST',body:JSON.stringify({action:clockAction,location_slug:locationSlug})});const messages={in:'Clocked on. Your shift is now recording.',break_start:'Break started.',break_end:`Break ended · ${result.break_minutes} minutes recorded.`,out:`Clocked off · ${Number(result.hours||0).toFixed(2)} paid hours recorded.`};toast(messages[clockAction]||'Working-hours record updated.');await renderRoute({preserveScroll:true});}
