      if(action==='refresh-xero-invoice'){await api(`/api/admin/billing/invoices/${Number(target.dataset.invoiceId)}/refresh-xero`,{method:'POST'});toast('Invoice status refreshed from Xero.');await renderRoute({preserveScroll:true});}
      if(action==='connect-xero'){if(target.dataset.configured!=='true'){toast('Add the Xero OAuth credentials to the secure server settings first.');return;}location.href='/api/integrations/xero/connect';}
      if(action==='preview-xero-readiness'){const result=await api('/api/integrations/xero/sync-timesheets',{method:'POST'});const output=document.getElementById('xero-readiness-output');if(output){output.className='xero-readiness-output';output.setAttribute('role','region');output.setAttribute('aria-label','Xero approved-hours readiness result');output.removeAttribute('aria-live');output.innerHTML=xeroReadinessMarkup(result);output.focus({preventScroll:true});}toast('Readiness preview complete. Payroll data was not sent.');}
      if(action==='set-account-status'){const active=target.dataset.accountActive==='true';await api(`/api/admin/accounts/${Number(target.dataset.accountId)}/status`,{method:'PATCH',body:JSON.stringify({active})});toast(active?'Account activated. The person can sign in again.':'Account suspended and all active sessions revoked.');await renderRoute({preserveScroll:true});}
      if(action==='save-enquiry'){const id=Number(target.dataset.enquiryId);const status=document.getElementById(`enquiry-status-${id}`).value;const owner=document.getElementById(`enquiry-owner-${id}`).value;const dateField=document.getElementById(`enquiry-date-${id}`);if(!dateField.reportValidity())return;await api(`/api/admin/enquiries/${id}`,{method:'PATCH',body:JSON.stringify({status,revision:Number(target.dataset.enquiryRevision),assigned_to:owner?Number(owner):null,next_action:document.getElementById(`enquiry-action-${id}`).value,follow_up_on:dateField.value||null})});toast('Enquiry follow-up status saved.');await renderRoute({preserveScroll:true});}
